use conduit_core::{StructuredInfoValue as V,StructuredInfoValueShape as S,StructuredInfoTypeShape as T,StructuredFieldValue as F};
use conduit_plot::{parse_syntax_document,check_syntax_document,StartupCatalog,CheckedNativeType};
use conduit_plot::rust_binding::validate_native_invariants;
fn field<'a>(v:&'a V,n:&str)->&'a V{let S::Record(f)=v.shape()else{panic!("record")};f.iter().find(|f|f.name()==n).unwrap().value()}
fn at(v:&V,i:usize)->&V{let S::Collection(v)=v.shape()else{panic!("collection")}; &v[i]}
fn num(v:&V)->u64{let S::Leaf(b)=v.shape()else{panic!("leaf")};u64::from_le_bytes(b.try_into().unwrap())}
fn scalar(t:&CheckedNativeType,n:&str,v:u64)->V{let T::Record{fields,..}=t.value_type.shape()else{panic!()};V::leaf(fields.iter().find(|f|f.name()==n).unwrap().value_type().clone(),v.to_le_bytes().to_vec()).unwrap()}
fn record(t:&CheckedNativeType,fs:Vec<(&str,V)>)->Result<V,String>{let v=V::record(t.value_type.clone(),fs.into_iter().map(|(n,v)|F::new(n,v).unwrap()).collect()).unwrap();validate_native_invariants(&v,&t.invariants).map_err(|e|format!("{e:?}"))?;Ok(v)}
fn expression(n:&conduit_plot::PortableExpressionNode)->String{use conduit_plot::PortableExpressionOperation as O;match &n.operation{O::Input=>"input".into(),O::Literal(v)=>v.clone(),O::Projection{value,member}=>format!("{}.({member:?})",expression(value)),O::Unary{operator,operand}=>format!("({operator:?} {})",expression(operand)),O::Binary{operator,left,right,..}=>format!("({} {operator:?} {})",expression(left),expression(right)),O::Conditional{condition,when_true,when_false}=>format!("({} ? {} : {})",expression(condition),expression(when_true),expression(when_false)),O::SemanticCall{kind,arguments}=>format!("{kind}({})",arguments.iter().map(expression).collect::<Vec<_>>().join(",")),_=>"aggregate".into()}}
fn main(){let root=std::path::Path::new("/home/dancxjo/conduit-4907-native-admission/semantics/language");let src=["types","identity","coverage","syntax","text_revision","revision_lineage","lexical","parser","parser_window8","parser_window8_search","parser_window8_facts","parser_beam","parser_scorer","parser_mask","parser_window8_dependency_facts"].iter().map(|n|std::fs::read_to_string(root.join(format!("{n}.conduit"))).unwrap()).collect::<Vec<_>>().join("\n");let c=check_syntax_document(&parse_syntax_document(&src),&StartupCatalog::new()).unwrap();let ty=|n:&str|c.native_types.iter().find(|t|t.name==n).unwrap();let qt=ty("LanguageParserWindow8FactQuery");let ct=ty("LanguageParserWindow8DependencyFactContext");let ft=ty("LanguageParserWindow8StableDependencyFact");
println!("fact_invariants={} context_invariants={}",ft.invariants.len(),ct.invariants.len());
if std::env::args().any(|a|a=="--laws-only"){for i in [17usize,19,49]{println!("law_index={i} {}",expression(&ft.invariants[i].root));}return;}
for epoch in 3..=11{let value=V::from_canonical_bytes(&std::fs::read(format!("work/immutable-dependency-probe/epoch-{epoch}.bin")).unwrap()).unwrap();assert_eq!(field(&value,"query").value_type(), &qt.value_type, "exact original query Type");let snapshot=field(field(&value,"query"),"snapshot");let lexical=field(snapshot,"lexical");let tokens=field(field(lexical,"tape"),"tokens");let state=field(field(field(snapshot,"candidate0"),"hypothesis"),"state");for dep in 0..6{let q=record(qt,vec![("snapshot",snapshot.clone()),("dependent",scalar(qt,"dependent",dep))]).unwrap();let head=num(at(field(state,"heads"),dep as usize));let relation=field(state,&format!("relation{dep}"));let S::Variant{tag,..}=field(relation,"base").shape()else{panic!()};let de=num(field(field(at(tokens,dep as usize),"span"),"end"));let he=if head>=6{0}else{num(field(field(at(tokens,head as usize),"span"),"end"))};let context=record(ct,vec![("query",q),("head",scalar(ct,"head",head)),("relation",relation.clone()),("dependent_end",scalar(ct,"dependent_end",de)),("head_end",scalar(ct,"head_end",he))]);let result=context.and_then(|v|record(ft,vec![("context",v)]));println!("epoch={epoch} dep={dep} head={head} relation={tag} result={}",match result{Ok(_)=>"accepted".into(),Err(e)=>e});}}}
